function UIHomeGatherActivityDialog:AddRedCommonRed()
    local openType = comp:GetOpenType()
    local index = 0
    for i, v in pairs(openType) do
        if checkInt(v) > GatherActivityQuestStartId then
            index = i
            break
        end
    end
    if index == 0 then
        return
    end
    ---@type UnityEngine.Transform
    local transform = self.roleStageObject.gameObject.transform
    local buttonGroup = transform:Find("Root/ButtonGroup")
    local buttonTrans = buttonGroup.transform
    ---@type UnityEngine.GameObject
    local btn = buttonTrans:Find(string.format("Button_%s", index))
    GameUtils.BindRedPoint(Constants.RedPointConst.GatherActivityQuest, btn.gameObject, true)
end

function UIHomeGatherActivityDialog:AddDrawRewardClick()
    local transform = self.roleStageObject.gameObject.transform
    local infoGroup = transform:Find("Root/InfoGroup")
    local imgFrame = infoGroup.transform:Find("ImgFrame")
    if isNull(imgFrame) then
        return
    end
    --local txtReceive = infoGroup.transform:Find("TxtReceive")
    SetButtonAction(imgFrame.gameObject, function()
        local _, isCan = comp:isCanRewards()
        if comp.isDrawReward == 1 then
            GameUtils.Toast(localize("奖励已领取"))
            return
        end
        if isCan ~= true then
            --GameUtils.Toast(localize("道具不足"))
            return
        end
        GameUtils.Request(Interfaces.ActivityDrawCardCollection, { activityUuid = comp.activityUuid }, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local data = response.data
                GoodsUtils.DrawRewards(data.rewards)
                CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards } })
                comp.isDrawReward = 1
                local txtHasReceived = infoGroup.transform:Find("TxtHasReceived")
                local TxtReceive = infoGroup.transform:Find("TxtReceive")
                if not isNull(txtHasReceived) then
                    KTool.SetActive(txtHasReceived, true)
                    KTool.SetActive(TxtReceive, false)
                end
                comp:SetRewardsRedPointNum()
                GoodsUtils.ConsumeGoods(comp.consume)
            end
        end)
    end)
end

function UIHomeGatherActivityDialog:AddModuleButtonClick()
    ---@type UnityEngine.Transform
    local transform = self.roleStageObject.gameObject.transform
    local buttonGroup = transform:Find("Root/ButtonGroup")
    local buttonTrans = buttonGroup.transform
    if isNull(buttonGroup) then
        return
    end
    local bindClickArray = {
        Bind(self, self.OnClickOne),
        Bind(self, self.OnClickTwo),
        Bind(self, self.OnClickThree),
        Bind(self, self.OnClickFour),
        Bind(self, self.OnClickFive)
    }
    local index = #comp:GetOpenType()
    for i = 1, index do
        local btn = buttonTrans:Find("Button_" .. i)
        if isNull(btn) then
            break
        end
        local normalImage = btn.transform:Find("Normal/ImgButton")
        if normalImage then
            SetButtonAction(normalImage.gameObject, bindClickArray[i])
        end

        local lockImage = btn.transform:Find("Lock/ImgButton")
        if lockImage then
            SetButtonAction(lockImage.gameObject, bindClickArray[i])
        end

        local finishImage = btn.transform:Find("Finish/ImgButton")
        if finishImage then
            SetButtonAction(finishImage.gameObject, bindClickArray[i])
        end

    end

    local roleGroup = transform:Find("Root/RoleGroup")
    SetButtonAction(roleGroup, Bind(self, self.RoleGroupClick))

    local btnDetail = transform:Find("Root/InfoGroup/BtnDetail")
    if not isNull(btnDetail) then
        SetButtonAction(btnDetail, Bind(self, self.RoleGroupClick))
    end
end
function UIHomeGatherActivityDialog:RoleGroupClick()
    local goodsId = comp.handbookId

    -- self:DisEnabledCanvas()
    local goodsType = GoodsUtils.GetIdType(goodsId)
    local displayType = 0
    if goodsType == Constants.IDType.CharacterCard then
        displayType = Constants.RoleDisplayType.CARD
    elseif goodsType == Constants.IDType.CardSkin then
        displayType = Constants.RoleDisplayType.SKIN
    end
    local GachaponUtils = import('Game.Gachapon.GachaponUtils')
    if displayType == Constants.RoleDisplayType.CARD then
        GachaponUtils.OpenDetail(goodsId)
    elseif displayType == Constants.RoleDisplayType.SKIN then
        CfUtils.DialogOpen(Constants.UITypeIds.CommonStylePreView, { skinId = goodsId }, {
            { id = Constants.UITypeIds.UIHomeView },
            { id = self.controller.Argument.id }
        }, true)
    end
    -- Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
end
function UIHomeGatherActivityDialog:UpdateButton()
    --local unlocks = comp:GetOpenTypeUnlocks()
    ---@type UnityEngine.GameObject
    local transform = self.roleStageObject.gameObject.transform
    local buttonGroup = transform:Find("Root/ButtonGroup")
    local buttonTrans = buttonGroup.transform
    if isNull(buttonGroup) then
        return
    end
    local index = #comp:GetOpenType()
    for i = 1, index do
        local btn = buttonTrans:Find("Button_" .. i)
        if isNull(btn) then
            break
        end
        local transform = btn.transform
        local unlockNodes = {
            Lock = transform:Find("Lock"),
            Normal = transform:Find("Normal"),
            Finish = transform:Find("Finish")
        }
        local nodeName = comp:GetUnlockStatusNodeName(i)
        for key, node in pairs(unlockNodes) do
            if not isNull(node) then
                KTool.SetActive(node.gameObject, key == nodeName)
            end
        end
    end
end

function UIHomeGatherActivityDialog:RefreshInfo()
    local transform = self.roleStageObject.gameObject.transform
    local infoGroup = transform:Find("Root/InfoGroup")
    ---@type UnityEngine.Transform
    local txtDate = infoGroup.transform:Find("TxtDate")
    CfUtils.FillCfText(txtDate, os.date("%Y.%m.%d", comp.startTime) .. "-" .. os.date("%Y.%m.%d  %H:%M", comp.endTime))
    local isDrawReward = comp.isDrawReward
    local txtNumber = infoGroup.transform:Find("TxtNumber")
    if isDrawReward ~= 0 then
        local txtHasReceived = infoGroup.transform:Find("TxtHasReceived")
        local TxtReceive = infoGroup.transform:Find("TxtReceive")
        if not isNull(txtHasReceived) then
            KTool.SetActive(txtHasReceived, true)
            KTool.SetActive(txtNumber, false)
            KTool.SetActive(TxtReceive, false)
        end
    else
        local _, isCan = comp:isCanRewards()
        local TxtReceive = infoGroup.transform:Find("TxtReceive")
        if isCan == true then
            KTool.SetActive(txtNumber, false)
            KTool.SetActive(TxtReceive, true)
        else
            if comp.consume and #comp.consume > 0 then
                local needNum = comp.consume[1].num
                local ownerNum = GoodsUtils.GetThingNo(comp.consume[1].goodsId)
                CfUtils.FillText(txtNumber, ownerNum .. "/" .. needNum)
            end
        end
    end
    local goodNode = infoGroup.transform:Find("GoodNode")
    if #comp.consume > 0 then
        if not isNull(goodNode) then
            local GoodNodeMBPath = "Game.Behaviours.GoodNodeMB"
            local goodItemNodeMB = GetLuaBehaviour(goodNode.gameObject, GoodNodeMBPath)
            if not isNull(goodItemNodeMB) then
                if isNull(goodItemNodeMB.Env) then
                    goodItemNodeMB:Init()
                end
                ---@type GoodNodeMB
                local goodItemNodeEnv = goodItemNodeMB.Env

                goodItemNodeEnv:Reload({
                    goodsId = comp.rewards[1].goodsId
                })
                goodItemNodeEnv:SetRoleGradeAndCareerState(true, comp.rewards[1].goodsId)
                goodItemNodeEnv:SetClickButtonAction(function(goodsId)
                    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                    if isTable(vo) then
                        --UIModule.CloseDialog(self.controller)
                        local GachaponUtils = import('Game.Gachapon.GachaponUtils')
                        local excludeDialogs = {

                            { id = Constants.UITypeIds.CultivateEntry },
                            { id = Constants.UITypeIds.BeginnerEventDialog },
                            { id = Constants.UITypeIds.RewardSelect },
                            { id = Constants.UITypeIds.UIHomeView },
                            { id = Constants.UITypeIds.UIMazeTeamDialog },
                            { id = Constants.UITypeIds.GachaponEntry },
                            --{ id = Constants.UITypeIds.GachaponMember},
                            { id = Constants.UITypeIds.GachaponResultViewNew },
                            { id = Constants.UITypeIds.GachaponResultViewSpecial },
                            { id = Constants.UITypeIds.GachaponCheckCache },
                            { id = Constants.UITypeIds.UIActivityMainDialog },
                            { id = Constants.UITypeIds.CommonActivityListDialog },
                            { id = self.controller.Argument.id },
                        }
                        GachaponUtils.OpenDetail(vo.id, excludeDialogs)
                        Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
                        --GameUtils.ShowCommonTipsBoard(goodNode, vo.name, vo.desc, vo.quality, vo.id)
                    end
                end)
            end
        end
    end
    if isNull(comp.consume) or #comp.consume == 0 then
        return
    end
    local ImgIcon = infoGroup.transform:Find("ImgIcon/ImgIcon")
    if not isNull(ImgIcon) then
        local ImageAlterable = CS.Engine.UI.ImageAlterable
        local ImageAlterableType = typeof(ImageAlterable)
        ---@type UnityEngine.GameObject
        local ImgIconObject = ImgIcon.gameObject
        ---@type Engine.UI.ImageAlterable
        local ImgIconAlterable = ImgIconObject:GetComponent(ImageAlterableType)
        local path = GoodsConfMgr:GetInstance():GetPhotoPathById(comp.consume[1].goodsId)
        ImgIconAlterable:LoadSprite(path)
        SetButtonAction(ImgIconObject.transform.parent, function()
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(comp.consume[1].goodsId)
            if isTable(goodsVo) then
                GameUtils.ShowCommonTipsBoard(ImgIconObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
            end
        end)
    end
end

