function UIHomeGatherActivityDialog:ExecuteJump(index)
    local KCookie = CS.Engine.Lib.KCookie
    local openTypes = comp:GetOpenType()
    local openParameters = comp:GetOpenParameters()
    local moduleId = checkInt(openTypes[index])
    local param = openParameters[index]
    local unlockStatus = comp:GetUnlockStatus()
    local status = checkInt(unlockStatus[index])
    if status == 0 then
        GameUtils.Toast(localize("活动尚未开启，敬请期待"))
        return
    end
    if checkInt(unlockStatus[index]) < 0 then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    xRecord.record('10-004', string.format('click_gather_activity_%d_%d', checkInt(comp.activityUuid), checkInt(index)))
    -- 跳转前预处理数据
    if moduleId == GatherModules.MainBattlePanelTwo then
        KCookie.Set("UIMainBattlePanelDialogIndex", 2)
        KCookie.Set("UIMainBattlePanelDialogChildIndex", checkInt(param))
    end

    print("param ===>", param)
    if moduleId < GatherActivityQuestStartId then
        self:__ExecuteJump(moduleId, param)
        return
    end
    --如果是体验关卡 并且 关联id大于零
    if comp.moduleId > 0 then
        self:__ExecuteJump(comp.moduleId, param)
        return
    end

    -- 关卡跳转
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose,
                          parameters = { levelId = comp.cardExperienceQuestId, activityUuid = comp.activityUuid } },
            {

                { id = Constants.UITypeIds.UIHomeView },
                { id = self.controller.Argument.id }

            })
end

function UIHomeGatherActivityDialog:__ExecuteJump(moduleId, param)
    local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
    blocker:AddCondition("__ExecuteJump")
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    xTry(function()
        cs_coroutine.start(function()
            Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
            --[[
            local isShow = false
            GameUtils.ShowBlackOverlay(nil, function()
                while not isShow do
                    coroutine.yield(Yielders.EndOfFrame)
                end
            end)
            coroutine.yield(WaitForSeconds(0.5))
            ]]
            local row = goodsConfMgr:GetJumpModuleRow(moduleId)
            if row then
                if not goodsConfMgr:CheckIsCanJump(row) then
                    blocker:RemoveCondition("__ExecuteJump")
                    return
                end
                self:DisEnabledCanvas()
                cs_coroutine.yield_return(goodsConfMgr:ExecuteJump(row, {}, 0, nil, param))
            end
            --coroutine.yield(WaitForSeconds(5))
            --isShow = true
            blocker:RemoveCondition("__ExecuteJump")
        end)
    end, function()
        print_to_file(debug.traceback())
        blocker:RemoveCondition("__ExecuteJump")
    end)
end
