--- 跳转场景的时候先设置canvas 为enabled 状态
function UIHomeGatherActivityDialog:DisEnabledCanvas()
    ---@type UnityEngine.Transform
    local transform = self.roleStageObject.gameObject.transform
    local rootCanvas = transform:GetComponent(typeof(CS.UnityEngine.Canvas))
    -- 根结点设置为false
    if not isNull(rootCanvas) then
        rootCanvas.enabled = false
    end
    -- 子节点的canvas
    local buttonGroup = transform:Find("Root/ButtonGroup")
    ---@type UnityEngine.Canvas[]
    local canvasArr = buttonGroup.gameObject:GetComponentsInChildren(typeof(CS.UnityEngine.Canvas))
    if not isNull(canvasArr) and canvasArr.Length then
        for i = 1, canvasArr.Length do
            canvasArr[i - 1].enabled = false
        end
    end
    local transform = self.roleStageObject.gameObject.transform
    local infoGroup = transform:Find("Root/InfoGroup")
    ---@type UnityEngine.Transform
    local txtDate = infoGroup.transform:Find("TxtDate")
    if not isNull(txtDate) then
        local canvas = txtDate:GetComponent(typeof(CS.UnityEngine.Canvas))
        if not isNull(canvas) then
            canvas.enabled = false
        end
    end
end
function UIHomeGatherActivityDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.GatherActivityQuest)
            GameUtils.SetRedPointNum(Constants.RedPointConst.GatherActivityFirstOpen, 0)
            GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.GatherActivityFirstOpen)
            comp:SetFirstOpen()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end
return UIHomeGatherActivityDialog